body:
The URL validation only checks for `http://` and `https://` prefixes, but doesn't handle relative URLs which are common in web applications. Relative URLs like `/dashboard`, `./page`, or `../parent` are legitimate and should be allowed for internal navigation.

Additionally, the current validation will incorrectly reject:
- Protocol-relative URLs: `//example.com/path`
- Anchor links: `#section`
- Mailto links (if needed): `mailto:user@example.com`

Consider expanding the validation to allow relative URLs, or clarifying in documentation that this field is only for absolute HTTP(S) URLs.
```suggestion
const isSafeHref = (raw: string): boolean => {
  if (!raw) return false;

  const value = raw.trim();
  const lower = value.toLowerCase();

  // Explicitly block dangerous schemes
  if (lower.startsWith('javascript:')) return false;
  if (lower.startsWith('data:')) return false;

  // Allow standard HTTP(S) URLs
  if (lower.startsWith('http://') || lower.startsWith('https://')) return true;

  // Allow protocol-relative URLs (e.g. //example.com/path)
  if (value.startsWith('//')) return true;

  // Allow in-page anchors (e.g. #section)
  if (value.startsWith('#')) return true;

  // Allow common relative URL patterns (e.g. /dashboard, ./page, ../parent)
  if (value.startsWith('/') || value.startsWith('./') || value.startsWith('../')) return true;

  // Allow mailto links for email addresses
  if (lower.startsWith('mailto:')) return true;

  // Block all other schemes by default
  return false;
};

export function UrlField({ value, onChange, field, readonly, errorMessage, ...props }: FieldWidgetProps<string>) {
  if (readonly) {
    if (!value) return <span className="text-sm">-</span>;

    // Validate URL to prevent dangerous schemes while allowing common safe patterns
    const isValidUrl = isSafeHref(value);
```
